"""MIRA-owned, opt-in Codex subscription OAuth session lifecycle.

This speaks only to the fixed auth.openai.com device/token endpoints. It never
discovers, reads, imports, or writes Codex CLI/Hermes credential stores.
"""
from __future__ import annotations

import asyncio
import base64
import contextlib
import json
import math
import os
import socket
import ssl
import tempfile
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Iterator, Protocol
from urllib.parse import urlsplit

import httpcore
import httpx
from pydantic import SecretStr

CODEX_OAUTH_CLIENT_ID = "app_EMoamEEZ73f0CkXaXp7hrann"
CODEX_AUTH_BASE_URL = "https://auth.openai.com"
CODEX_DEVICE_CODE_URL = (
    "https://auth.openai.com/api/accounts/deviceauth/usercode"
)
CODEX_DEVICE_TOKEN_URL = (
    "https://auth.openai.com/api/accounts/deviceauth/token"
)
CODEX_OAUTH_TOKEN_URL = "https://auth.openai.com/oauth/token"
CODEX_DEVICE_VERIFICATION_URL = "https://auth.openai.com/codex/device"
CODEX_DEVICE_REDIRECT_URI = "https://auth.openai.com/deviceauth/callback"

REFRESH_SKEW_SECONDS = 120
DEFAULT_DEVICE_FLOW_TIMEOUT_SECONDS = 900
MAX_AUTH_RESPONSE_BYTES = 1_048_576
MAX_TOKEN_CHARS = 65_536
_STORE_VERSION = 1
_LOCK_TIMEOUT_SECONDS = 30.0
__all__ = [
    "CODEX_AUTH_BASE_URL",
    "CODEX_DEVICE_CODE_URL",
    "CODEX_DEVICE_TOKEN_URL",
    "CODEX_DEVICE_VERIFICATION_URL",
    "CODEX_OAUTH_CLIENT_ID",
    "CODEX_OAUTH_TOKEN_URL",
    "CodexAuthError",
    "CodexCredentialSource",
    "CodexOAuthCredentialSource",
    "CodexOAuthCredentials",
    "CodexSessionStore",
    "default_session_path",
]


class CodexAuthError(RuntimeError):
    """Safe, fixed-code auth error; messages never include server text or secrets."""

    def __init__(self, code: str, *, diagnostic: dict[str, object] | None = None):
        self.code = code
        self._diagnostic = diagnostic
        super().__init__(code)

    def safe_diagnostic(self) -> dict[str, object] | None:
        """Return only fixed labels and bounded integers, never exception text."""
        if self._diagnostic is None:
            return None
        return _sanitize_network_diagnostic(self._diagnostic)


def _known_exception_types() -> list[tuple[type[BaseException], str, str]]:
    # Labels are constants, never arbitrary class names or exception messages.
    known = [
        (ssl.SSLCertVerificationError, "ssl.SSLCertVerificationError", "tls_certificate"),
        (ssl.SSLError, "ssl.SSLError", "tls"),
        (socket.gaierror, "socket.gaierror", "dns"),
        (ConnectionRefusedError, "builtins.ConnectionRefusedError", "connection_refused"),
        (ConnectionResetError, "builtins.ConnectionResetError", "connection_reset"),
        (TimeoutError, "builtins.TimeoutError", "timeout"),
    ]
    names = (
        ("ProxyError", "proxy"), ("ConnectTimeout", "connect_timeout"),
        ("ReadTimeout", "read_timeout"), ("WriteTimeout", "write_timeout"),
        ("PoolTimeout", "pool_timeout"), ("ConnectError", "connect"),
        ("ReadError", "read"), ("WriteError", "write"), ("CloseError", "close"),
        ("RemoteProtocolError", "remote_protocol"),
        ("LocalProtocolError", "local_protocol"),
        ("UnsupportedProtocol", "unsupported_protocol"),
        ("DecodingError", "response_decoding"), ("RequestError", "request"),
    )
    for module, prefix in ((httpx, "httpx"), (httpcore, "httpcore")):
        for name, category in names:
            cls = getattr(module, name, None)
            if isinstance(cls, type) and issubclass(cls, BaseException):
                known.append((cls, prefix + "." + name, category))
    known.extend(((OSError, "builtins.OSError", "os_error"),
                  (ValueError, "builtins.ValueError", "value_error"),
                  (RuntimeError, "builtins.RuntimeError", "runtime_error")))
    return known


def _safe_exception_fields(error: BaseException) -> dict[str, object]:
    """Inspect bounded cause/context chains without reading args, request or text."""
    chain: list[dict[str, object]] = []
    categories: list[str] = []
    seen: set[int] = set()
    pending = [error]
    while pending and len(chain) < 16:
        item = pending.pop(0)
        if id(item) in seen:
            continue
        seen.add(id(item))
        label, category = "unrecognized_exception", "unrecognized"
        for cls, known_label, known_category in _known_exception_types():
            if isinstance(item, cls):
                label, category = known_label, known_category
                break
        entry: dict[str, object] = {"type": label}
        if isinstance(item, OSError):
            number = item.errno
            if type(number) is int and -65535 <= number <= 65535:
                entry["errno"] = number
        if isinstance(item, ssl.SSLCertVerificationError):
            number = getattr(item, "verify_code", None)
            if type(number) is int and 0 <= number <= 65535:
                entry["ssl_verify_code"] = number
        chain.append(entry)
        if category not in categories:
            categories.append(category)
        for linked in (item.__cause__, item.__context__):
            if isinstance(linked, BaseException) and id(linked) not in seen:
                pending.append(linked)
    return {"categories": categories, "exception_chain": chain,
            "chain_truncated": bool(pending)}


def _sanitize_network_diagnostic(value: object) -> dict[str, object]:
    # Validate again at the display boundary; no caller-controlled strings escape.
    value = value if type(value) is dict else {}
    operations = {"device_code_request", "device_code_poll", "token_exchange", "token_refresh"}
    phases = {"client_initialization", "request_headers", "response_body",
              "response_reconstruction", "response_close", "client_close"}
    result: dict[str, object] = {"diagnostic": "mira_oauth_failure_v1", "category": "exception"}
    for key, allowed in (("operation", operations), ("phase", phases)):
        label = value.get(key)
        result[key] = label if type(label) is str and label in allowed else "unknown"
    status = value.get("http_status")
    if type(status) is int and 100 <= status <= 599:
        result["http_status"] = status
    metadata_labels = {
        "content_encoding": {"none", "identity", "gzip", "deflate", "br", "zstd", "multiple", "other"},
        "content_length_bucket": {"empty", "small_1_4096", "medium_4097_65536",
                                  "large_65537_1048576", "over_limit", "unknown"},
        "decoded_bytes_bucket": {"empty", "small_1_4096", "medium_4097_65536",
                                 "large_65537_1048576", "over_limit", "unknown"},
    }
    for key, allowed in metadata_labels.items():
        if key in value:
            label = value.get(key)
            result[key] = label if type(label) is str and label in allowed else "unknown"
    known = _known_exception_types()
    labels = {label for _, label, _ in known} | {"unrecognized_exception"}
    categories = {category for _, _, category in known} | {"unrecognized"}
    raw_categories = value.get("categories")
    result["categories"] = [item for item in raw_categories[:16]
                            if type(item) is str and item in categories
                            ] if type(raw_categories) is list else []
    raw_chain = value.get("exception_chain")
    chain: list[dict[str, object]] = []
    if type(raw_chain) is list:
        for entry in raw_chain[:16]:
            if type(entry) is not dict:
                continue
            label = entry.get("type")
            safe: dict[str, object] = {
                "type": label if type(label) is str and label in labels else "unrecognized_exception"
            }
            for key, minimum in (("errno", -65535), ("ssl_verify_code", 0)):
                number = entry.get(key)
                if type(number) is int and minimum <= number <= 65535:
                    safe[key] = number
            chain.append(safe)
    result["exception_chain"] = chain
    result["chain_truncated"] = value.get("chain_truncated") is True
    return result


def _safe_content_encoding(value: object) -> str:
    """Classify the encoding field; never return an arbitrary header value."""
    if value is None or value == "":
        return "none"
    if type(value) is not str or len(value) > 128:
        return "other"
    normalized = value.strip().lower()
    if normalized in {"identity", "gzip", "deflate", "br", "zstd"}:
        return normalized
    return "multiple" if "," in normalized else "other"


def _byte_count_bucket(value: object) -> str:
    if type(value) is not int or value < 0:
        return "unknown"
    if value == 0:
        return "empty"
    if value <= 4096:
        return "small_1_4096"
    if value <= 65536:
        return "medium_4097_65536"
    if value <= MAX_AUTH_RESPONSE_BYTES:
        return "large_65537_1048576"
    return "over_limit"


def _safe_content_length_bucket(value: object) -> str:
    if (type(value) is not str or not 1 <= len(value) <= 12
            or not value.isascii() or not value.isdecimal()):
        return "unknown"
    return _byte_count_bucket(int(value))


def _auth_operation(url: str, data: dict[str, str] | None) -> str:
    if url == CODEX_DEVICE_CODE_URL:
        return "device_code_request"
    if url == CODEX_DEVICE_TOKEN_URL:
        return "device_code_poll"
    if url == CODEX_OAUTH_TOKEN_URL and data is not None:
        if data.get("grant_type") == "authorization_code":
            return "token_exchange"
        if data.get("grant_type") == "refresh_token":
            return "token_refresh"
    return "unknown"


@dataclass(frozen=True, slots=True)
class CodexOAuthCredentials:
    """Opaque in-process credentials for a selected direct subscription route."""

    access_token: SecretStr = field(repr=False)
    account_id: str | None = field(default=None, repr=False)
    residency: str | None = field(default=None, repr=False)


class CodexCredentialSource(Protocol):
    async def get_credentials(self) -> CodexOAuthCredentials: ...


@dataclass(frozen=True, slots=True)
class _Session:
    access_token: str = field(repr=False)
    refresh_token: str = field(repr=False)
    expires_at: float
    revision: int
    account_id: str | None = field(default=None, repr=False)
    residency: str | None = field(default=None, repr=False)


def default_session_path() -> Path:
    """Return MIRA's private app-owned location without touching it."""
    if os.name == "nt":
        root = Path.home() / "AppData" / "Local"
        return root / "MIRA" / "auth" / "openai-codex-session.json"
    if sys_platform_is_macos():
        return Path.home() / "Library" / "Application Support" / "MIRA" / "auth" / "openai-codex-session.json"
    return Path.home() / ".local" / "share" / "mira" / "auth" / "openai-codex-session.json"


def sys_platform_is_macos() -> bool:
    # Kept local so importing this module has no filesystem or network side effects.
    import sys

    return sys.platform == "darwin"


def _object_no_duplicates(pairs: list[tuple[str, object]]) -> dict[str, object]:
    out: dict[str, object] = {}
    for key, value in pairs:
        if key in out:
            raise ValueError("duplicate key")
        out[key] = value
    return out


def _json_object(raw: bytes, error_code: str) -> dict[str, object]:
    if len(raw) > MAX_AUTH_RESPONSE_BYTES:
        raise CodexAuthError(error_code)
    try:
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=_object_no_duplicates)
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError, RecursionError):
        raise CodexAuthError(error_code) from None
    if type(value) is not dict:
        raise CodexAuthError(error_code)
    return value


def _assert_outside_checkout(path: Path) -> None:
    try:
        checkout_root = Path(__file__).resolve().parents[6]
        candidate = path.resolve()
    except (OSError, IndexError):
        raise CodexAuthError("auth_store_path_invalid") from None
    if candidate.is_relative_to(checkout_root):
        raise CodexAuthError("auth_store_must_be_outside_checkout")


def _private_dir(path: Path) -> None:
    _assert_outside_checkout(path)
    path.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.is_symlink() or not path.is_dir():
        raise CodexAuthError("auth_store_path_invalid")
    if os.name != "nt":
        mode = path.stat().st_mode & 0o777
        if mode & 0o077:
            raise CodexAuthError("auth_store_directory_not_private")


@contextlib.contextmanager
def _file_lock(lock_path: Path) -> Iterator[None]:
    """Cross-process advisory lock; lock file is owned by this MIRA auth directory."""
    _private_dir(lock_path.parent)
    if lock_path.is_symlink():
        raise CodexAuthError("auth_store_path_invalid")
    fd = os.open(lock_path, os.O_CREAT | os.O_RDWR, 0o600)
    acquired = False
    try:
        if os.name == "nt":
            import msvcrt

            if os.fstat(fd).st_size == 0:
                os.write(fd, b"\0")
                os.lseek(fd, 0, os.SEEK_SET)
            deadline = time.monotonic() + _LOCK_TIMEOUT_SECONDS
            while True:
                try:
                    msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                    acquired = True
                    break
                except OSError:
                    if time.monotonic() >= deadline:
                        raise CodexAuthError("auth_store_lock_timeout") from None
                    time.sleep(0.05)
        else:
            import fcntl

            deadline = time.monotonic() + _LOCK_TIMEOUT_SECONDS
            while True:
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    acquired = True
                    break
                except BlockingIOError:
                    if time.monotonic() >= deadline:
                        raise CodexAuthError("auth_store_lock_timeout") from None
                    time.sleep(0.05)
        yield
    finally:
        if acquired:
            if os.name == "nt":
                import msvcrt

                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def _atomic_private_json(path: Path, payload: dict[str, object]) -> None:
    """Atomically write one private JSON file next to its destination."""
    _private_dir(path.parent)
    if path.is_symlink():
        raise CodexAuthError("auth_store_path_invalid")
    encoded = (json.dumps(payload, separators=(",", ":"), sort_keys=True) + "\n").encode()
    fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    temp_path = Path(temp_name)
    try:
        if os.name != "nt":
            os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp_path, path)
        if os.name != "nt":
            os.chmod(path, 0o600)
        if os.name != "nt":
            dir_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
    except Exception:
        with contextlib.suppress(FileNotFoundError):
            temp_path.unlink()
        raise


def _session_payload(session: _Session) -> dict[str, object]:
    return {
        "version": _STORE_VERSION,
        "state": "authenticated",
        "revision": session.revision,
        "access_token": session.access_token,
        "refresh_token": session.refresh_token,
        "expires_at": session.expires_at,
        "account_id": session.account_id,
        "residency": session.residency,
    }


def _read_session(path: Path) -> _Session | None:
    _assert_outside_checkout(path)
    if path.is_symlink():
        raise CodexAuthError("auth_store_path_invalid")
    if not path.exists():
        return None
    if os.name != "nt" and (path.stat().st_mode & 0o077):
        raise CodexAuthError("auth_store_file_not_private")
    try:
        raw = path.read_bytes()
    except OSError:
        raise CodexAuthError("auth_store_unreadable") from None
    if len(raw) > MAX_AUTH_RESPONSE_BYTES:
        raise CodexAuthError("auth_store_invalid")
    try:
        payload = _json_object(raw, "auth_store_invalid")
    except CodexAuthError:
        raise
    if payload.get("version") != _STORE_VERSION:
        raise CodexAuthError("auth_store_version_unsupported")
    state = payload.get("state")
    if state == "signed_out":
        return None
    if state != "authenticated":
        raise CodexAuthError("auth_store_invalid")
    access = payload.get("access_token")
    refresh = payload.get("refresh_token")
    expiry = payload.get("expires_at")
    revision = payload.get("revision")
    account_id = payload.get("account_id")
    residency = payload.get("residency")
    if (
        type(access) is not str
        or not access
        or len(access) > MAX_TOKEN_CHARS
        or type(refresh) is not str
        or not refresh
        or len(refresh) > MAX_TOKEN_CHARS
        or type(expiry) not in (int, float)
        or not math.isfinite(float(expiry))
        or type(revision) is not int
        or revision < 1
        or (account_id is not None and type(account_id) is not str)
        or (residency is not None and type(residency) is not str)
        or (isinstance(account_id, str) and (len(account_id) > 256 or any(ord(c) < 0x20 for c in account_id)))
        or (isinstance(residency, str) and (len(residency) > 256 or any(ord(c) < 0x20 for c in residency)))
    ):
        raise CodexAuthError("auth_store_invalid")
    return _Session(access, refresh, float(expiry), revision, account_id, residency)


def _token_fields(payload: dict[str, object]) -> tuple[str, str | None, float]:
    access = payload.get("access_token")
    refresh = payload.get("refresh_token")
    expires = payload.get("expires_in")
    if (
        type(access) is not str
        or not access
        or len(access) > MAX_TOKEN_CHARS
        or any(ord(char) < 0x20 for char in access)
        or (refresh is not None and type(refresh) is not str)
        or (isinstance(refresh, str) and (
            not refresh or len(refresh) > MAX_TOKEN_CHARS or any(ord(char) < 0x20 for char in refresh)
        ))
        or type(expires) not in (int, float)
        or not math.isfinite(float(expires))
        or float(expires) <= 0
    ):
        raise CodexAuthError("oauth_token_response_invalid")
    return access, refresh, float(expires)


def _jwt_account_metadata(access_token: str) -> tuple[str | None, str | None]:
    """Decode optional request metadata from the Codex access-token JWT.

    This deliberately does not validate identity or the JWT signature. OpenAI's
    backend remains the token validator; these two optional values only support
    the account/residency headers described in the pinned Hermes source review.
    """
    try:
        parts = access_token.split(".")
        if len(parts) < 2 or not parts[1]:
            return None, None
        payload_b64 = parts[1] + "=" * (-len(parts[1]) % 4)
        payload_bytes = base64.urlsafe_b64decode(payload_b64)
        claims = _json_object(payload_bytes, "oauth_token_metadata_invalid")
        auth_claims = claims.get("https://api.openai.com/auth")
        if type(auth_claims) is not dict:
            return None, None
        account = auth_claims.get("chatgpt_account_id")
        if (
            type(account) is not str
            or not account.strip()
            or len(account) > 256
            or any(ord(char) < 0x20 for char in account)
        ):
            account_id = None
        else:
            account_id = account.strip()
        residency = auth_claims.get("chatgpt_data_residency")
        if not (isinstance(residency, str) and residency.strip()):
            residency = auth_claims.get("chatgpt_compute_residency")
        if (
            type(residency) is not str
            or not residency.strip()
            or len(residency) > 256
            or any(ord(char) < 0x20 for char in residency)
        ):
            residency_value = None
        else:
            residency_value = residency.strip()
        return account_id, residency_value
    except (CodexAuthError, ValueError, TypeError, RecursionError):
        return None, None


def _fixed_auth_url(url: str) -> bool:
    parts = urlsplit(url)
    return (
        parts.scheme == "https"
        and parts.hostname == "auth.openai.com"
        and parts.port in (None, 443)
        and not parts.username
        and not parts.password
    )


def _response_payload(response: httpx.Response, code: str) -> dict[str, object]:
    if 300 <= response.status_code < 400:
        raise CodexAuthError("oauth_redirect_rejected")
    if response.status_code != 200:
        raise CodexAuthError(code)
    raw = response.content
    return _json_object(raw, code)


class CodexSessionStore:
    """MIRA's separate private store, refresh lock and device-code OAuth client."""

    def __init__(
        self,
        path: Path | None = None,
        *,
        transport: httpx.BaseTransport | None = None,
        clock: Callable[[], float] = time.time,
        monotonic: Callable[[], float] = time.monotonic,
        sleep: Callable[[float], None] = time.sleep,
    ) -> None:
        self.path = Path(path) if path is not None else default_session_path()
        self._transport = transport
        self._clock = clock
        self._monotonic = monotonic
        self._sleep = sleep
        self._lock_path = self.path.with_name(self.path.name + ".lock")
        self._backup_path = self.path.with_name(self.path.name + ".bak")

    def _client(self) -> httpx.Client:
        if self._transport is not None:
            return httpx.Client(
                transport=self._transport,
                timeout=httpx.Timeout(15.0),
                follow_redirects=False,
            )
        return httpx.Client(timeout=httpx.Timeout(15.0), follow_redirects=False)

    def _post_json(
        self, url: str, *, json_body: dict[str, object], data: dict[str, str] | None = None
    ) -> httpx.Response:
        if not _fixed_auth_url(url):
            raise CodexAuthError("oauth_endpoint_rejected")
        # Auth JSON is small; explicitly avoid optional compression negotiation.
        # A server may still compress: iter_bytes below decodes exactly once.
        headers = {"Accept": "application/json", "Accept-Encoding": "identity"}
        if data is None:
            headers["Content-Type"] = "application/json"
        else:
            headers["Content-Type"] = "application/x-www-form-urlencoded"
        phase = "client_initialization"
        http_status: int | None = None
        content_encoding = "none"
        content_length_bucket = "unknown"
        size = 0
        try:
            with self._client() as client:
                request_args: dict[str, object] = {"headers": headers}
                if data is None:
                    request_args["json"] = json_body
                else:
                    request_args["data"] = data
                phase = "request_headers"
                with client.stream("POST", url, **request_args) as streamed:
                    http_status = streamed.status_code
                    content_encoding = _safe_content_encoding(streamed.headers.get("content-encoding"))
                    content_length_bucket = _safe_content_length_bucket(streamed.headers.get("content-length"))
                    phase = "response_body"
                    chunks: list[bytes] = []
                    size = 0
                    for chunk in streamed.iter_bytes():
                        size += len(chunk)
                        if size > MAX_AUTH_RESPONSE_BYTES:
                            raise CodexAuthError("oauth_response_too_large")
                        chunks.append(chunk)
                    phase = "response_reconstruction"
                    # iter_bytes has already decoded Content-Encoding. Retaining
                    # it here would decode the JSON a second time. Framing must
                    # also describe the decoded body, not the wire representation.
                    decoded_headers = streamed.headers.copy()
                    for field_name in ("content-encoding", "content-length", "transfer-encoding"):
                        decoded_headers.pop(field_name, None)
                    response = httpx.Response(
                        streamed.status_code,
                        headers=decoded_headers,
                        content=b"".join(chunks),
                        request=streamed.request,
                    )
                    phase = "response_close"
                phase = "client_close"
        except CodexAuthError:
            raise
        except (httpx.RequestError, OSError, ValueError) as exc:
            diagnostic = {
                "operation": _auth_operation(url, data), "phase": phase,
                "http_status": http_status, "content_encoding": content_encoding,
                "content_length_bucket": content_length_bucket,
                "decoded_bytes_bucket": _byte_count_bucket(size), **_safe_exception_fields(exc),
            }
            raise CodexAuthError("oauth_network_error", diagnostic=diagnostic) from None
        if 300 <= response.status_code < 400:
            raise CodexAuthError("oauth_redirect_rejected")
        return response

    def begin_device_login(
        self,
        *,
        timeout_seconds: float = DEFAULT_DEVICE_FLOW_TIMEOUT_SECONDS,
        on_user_code: Callable[[str, str], None] | None = None,
    ) -> None:
        """Run a user-started device grant and persist only after token validation.

        `on_user_code` is the CLI presentation hook. The code is held only in this
        call's memory and is never logged or included in an exception.
        """
        if not math.isfinite(timeout_seconds) or timeout_seconds <= 0:
            raise ValueError("timeout_seconds must be finite and positive")
        start = self._post_json(
            CODEX_DEVICE_CODE_URL,
            json_body={"client_id": CODEX_OAUTH_CLIENT_ID},
        )
        start_data = _response_payload(start, "device_code_request_failed")
        device_auth_id = start_data.get("device_auth_id")
        user_code = start_data.get("user_code")
        interval_raw = start_data.get("interval")
        if type(interval_raw) is str:
            try:
                interval = float(interval_raw)
            except ValueError:
                raise CodexAuthError("device_code_response_invalid") from None
        elif type(interval_raw) in (int, float):
            interval = float(interval_raw)
        else:
            raise CodexAuthError("device_code_response_invalid")
        if (
            type(device_auth_id) is not str
            or not device_auth_id
            or len(device_auth_id) > 4096
            or any(ord(char) < 0x20 for char in device_auth_id)
            or type(user_code) is not str
            or not user_code
            or len(user_code) > 128
            or any(ord(char) < 0x20 for char in user_code)
            or not math.isfinite(interval)
            or interval < 0
        ):
            raise CodexAuthError("device_code_response_invalid")
        poll_interval = max(1.0, interval)
        if on_user_code is not None:
            on_user_code(CODEX_DEVICE_VERIFICATION_URL, user_code)
        deadline = self._monotonic() + timeout_seconds
        authorization_code: str | None = None
        code_verifier: str | None = None
        while self._monotonic() < deadline:
            self._sleep(min(poll_interval, max(0.0, deadline - self._monotonic())))
            if self._monotonic() >= deadline:
                break
            poll = self._post_json(
                CODEX_DEVICE_TOKEN_URL,
                json_body={"device_auth_id": device_auth_id, "user_code": user_code},
            )
            if poll.status_code == 200:
                poll_data = _response_payload(poll, "device_code_poll_failed")
                code = poll_data.get("authorization_code")
                verifier = poll_data.get("code_verifier")
                if (
                    type(code) is not str
                    or not code
                    or len(code) > 16_384
                    or any(ord(char) < 0x20 for char in code)
                    or type(verifier) is not str
                    or not verifier
                    or len(verifier) > 16_384
                    or any(ord(char) < 0x20 for char in verifier)
                ):
                    raise CodexAuthError("device_code_response_invalid")
                authorization_code, code_verifier = code, verifier
                break
            error_code = _oauth_error_code(poll)
            if error_code in {"deviceauth_authorization_pending", "authorization_pending"}:
                continue
            if error_code == "slow_down":
                poll_interval += 5.0
                continue
            if error_code in {"access_denied", "deviceauth_access_denied", "authorization_denied"}:
                raise CodexAuthError("device_code_denied")
            if error_code in {"expired_token", "deviceauth_expired", "authorization_expired"}:
                raise CodexAuthError("device_code_expired")
            if poll.status_code in {403, 404} and error_code is None:
                # The pinned device endpoint uses these statuses for an unapproved code.
                continue
            raise CodexAuthError("device_code_poll_failed")
        if authorization_code is None or code_verifier is None:
            raise CodexAuthError("device_code_timeout")
        exchange = self._post_json(
            CODEX_OAUTH_TOKEN_URL,
            json_body={},
            data={
                "grant_type": "authorization_code",
                "client_id": CODEX_OAUTH_CLIENT_ID,
                "code": authorization_code,
                "code_verifier": code_verifier,
                "redirect_uri": CODEX_DEVICE_REDIRECT_URI,
            },
        )
        exchange_data = _response_payload(exchange, "oauth_exchange_failed")
        access, refresh, expires_in = _token_fields(exchange_data)
        if not refresh:
            raise CodexAuthError("oauth_token_response_invalid")
        account_id, residency = _jwt_account_metadata(access)
        self._write_session(
            _Session(access, refresh, self._clock() + expires_in, 1, account_id, residency)
        )

    async def get_credentials(self) -> CodexOAuthCredentials:
        """Return a current MIRA-owned token; refresh only this explicit session."""
        return await asyncio.to_thread(self._get_credentials_sync)

    def _get_credentials_sync(self) -> CodexOAuthCredentials:
        with _file_lock(self._lock_path):
            session = _read_session(self.path)
            if session is None:
                raise CodexAuthError("codex_subscription_login_required")
            if session.expires_at > self._clock() + REFRESH_SKEW_SECONDS:
                return _credentials(session)
            response = self._post_json(
                CODEX_OAUTH_TOKEN_URL,
                json_body={},
                data={
                    "grant_type": "refresh_token",
                    "client_id": CODEX_OAUTH_CLIENT_ID,
                    "refresh_token": session.refresh_token,
                },
            )
            refreshed = _response_payload(response, "oauth_refresh_failed")
            access, rotated_refresh, expires_in = _token_fields(refreshed)
            refresh = rotated_refresh or session.refresh_token
            account_id, residency = _jwt_account_metadata(access)
            updated = _Session(
                access,
                refresh,
                self._clock() + expires_in,
                session.revision + 1,
                account_id,
                residency,
            )
            self._write_session_unlocked(updated)
            return _credentials(updated)

    def status(self) -> bool:
        """Read only MIRA's active store; never refresh or discover credentials."""
        # Atomic replacement keeps the primary file complete while we read it;
        # status must not create even a lock file or touch the provider.
        return _read_session(self.path) is not None

    def sign_out(self) -> None:
        """Disable the app-owned session locally; does not revoke provider tokens."""
        with _file_lock(self._lock_path):
            current = _read_session(self.path)
            revision = (current.revision + 1) if current is not None else 1
            tombstone = {
                "version": _STORE_VERSION,
                "state": "signed_out",
                "revision": revision,
            }
            _atomic_private_json(self.path, tombstone)

    def restore_backup(self) -> None:
        """Explicitly restore a recoverable MIRA backup; never auto-fallback to it."""
        with _file_lock(self._lock_path):
            session = _read_session(self._backup_path)
            if session is None:
                raise CodexAuthError("auth_backup_unavailable")
            _atomic_private_json(self.path, _session_payload(session))

    def discard_local_session(self) -> None:
        """Permanently remove only this MIRA session and its backup from local disk."""
        with _file_lock(self._lock_path):
            for path in (self.path, self._backup_path):
                if path.is_symlink():
                    raise CodexAuthError("auth_store_path_invalid")
                with contextlib.suppress(FileNotFoundError):
                    path.unlink()

    def _write_session(self, session: _Session) -> None:
        with _file_lock(self._lock_path):
            self._write_session_unlocked(session)

    def _write_session_unlocked(self, session: _Session) -> None:
        payload = _session_payload(session)
        # Stage the validated new token pair in the private backup first. If the
        # process stops before the main replace, an explicit restore can recover it.
        _atomic_private_json(self._backup_path, payload)
        _atomic_private_json(self.path, payload)


class CodexOAuthCredentialSource:
    """Convenience credential source for direct-provider composition.

    Construction is side-effect free. A store file is read, and an expired token
    may be refreshed, only on an explicit call to ``get_credentials``.
    """

    def __init__(
        self,
        store_path: Path | None = None,
        *,
        transport: httpx.BaseTransport | None = None,
        clock: Callable[[], float] = time.time,
        monotonic: Callable[[], float] = time.monotonic,
        sleep: Callable[[float], None] = time.sleep,
    ) -> None:
        self._store = CodexSessionStore(
            store_path, transport=transport, clock=clock, monotonic=monotonic, sleep=sleep
        )

    async def get_credentials(self) -> CodexOAuthCredentials:
        return await self._store.get_credentials()


def _credentials(session: _Session) -> CodexOAuthCredentials:
    return CodexOAuthCredentials(
        access_token=SecretStr(session.access_token),
        account_id=session.account_id,
        residency=session.residency,
    )


def _oauth_error_code(response: httpx.Response) -> str | None:
    try:
        payload = _json_object(response.content, "oauth_error_response_invalid")
    except CodexAuthError:
        return None
    error = payload.get("error")
    if type(error) is dict:
        code = error.get("code")
    else:
        code = error
    return code if type(code) is str and len(code) <= 128 else None

"""Allowlist encoding plus defensive credential filtering, not a universal DLP claim."""
import base64
import json
import math
import re
import unicodedata
from dataclasses import dataclass, fields

from mira.application.diagnostic_events import (
    CancellationReason,
    ContentReview,
    DiagnosticCode,
    DiagnosticContext,
    DiagnosticEvent,
    DiagnosticKind,
    DiagnosticOutcome,
    DiagnosticStage,
    RecordingKind,
    ReviewedRecording,
    correlation_hash,
)
from mira.application.contracts import (
    ReportedConfidenceWarning, ResponseChoice, ResponseValidationReason, ResponseWireType,
    SafeResponseAnswerFacts, SafeResponseValidation,
)
from mira.application.choice_wire_policy import (
    CHOICE_WIRE_POLICY_REPORTED_V2, SUPPORTED_CHOICE_WIRE_POLICIES,
)

_CONTEXT_KEYS = tuple(field.name for field in fields(DiagnosticContext))
_HASH = re.compile(r"h_[0-9a-f]{32}\Z")
_FORBIDDEN_ENVELOPE = re.compile(
    r'(?i)(?:authorization\s*[":=]|["\'](?:headers|private_key|client_secret|credentials|'
    r'access_token|refresh_token|id_token|password|api_key|x-api-key)["\']\s*:|'
    r'-----BEGIN [A-Z ]*PRIVATE KEY-----)')
_SECRET_SHAPES = (
    re.compile(r"(?i)(?<![A-Za-z0-9_-])[_-]*(?:[A-Za-z][A-Za-z0-9_-]*[_-])?(?:api[_-]?key|password|passwd|private[_-]?key|access[_-]?token|refresh[_-]?token|"
               r"client[_-]?secret|secret|credentials|token)\s*(?:=|:|\bis\b)\s*"
               r"(?:\"[^\"\r\n]*\"|'[^'\r\n]*')"),
    re.compile(r"(?i)\bBearer\s+[^\s,;\"']+"),
    re.compile(r"\b(?:sk-[A-Za-z0-9_-]{8,}|AIza[A-Za-z0-9_-]{20,}|AKIA[A-Z0-9]{16})\b"),
    re.compile(r"(?<![A-Za-z0-9_-])eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b"),
    re.compile(r"(?i)(?<![A-Za-z0-9_-])[_-]*(?:[A-Za-z][A-Za-z0-9_-]*[_-])?(?:api[_-]?key|password|passwd|private[_-]?key|access[_-]?token|refresh[_-]?token|"
               r"client[_-]?secret|secret|credentials|token)\s*(?:=|:|\bis\b)\s*[^\s,;\"']+"),
    re.compile(r"(?i)https?://[^\s/@:]+:[^\s/@]+@[^\s]+"),
)


# Raw text is deliberately a small, conservative language, not arbitrary encoding/DLP.
_MAX_TEXT_BYTES = 128 * 1024
_MAX_DEPTH = 16
_MAX_NODES = 4096
_MAX_REVIEW_CHARS = 1024 * 1024
_CREDENTIAL_KEYS = frozenset((
    "authorization", "proxyauthorization", "headers", "requestheaders", "httpheaders",
    "privatekey", "clientsecret", "credentials", "accesstoken", "refreshtoken",
    "idtoken", "password", "passwd", "apikey", "xapikey", "secret", "token",
    "cookie", "setcookie",
))
_QUOTED_ASSIGNMENT = re.compile(r"[\"']([^\"'\\\r\n]{1,256})[\"']\s*[:=]")
_JSON_START = re.compile(r"[\[{]")
_NON_JSON_ESCAPE = re.compile(r'\\(?:["\\]|u[0-9a-fA-F]{4})')
_RESPONSE_VALIDATION_KEYS = tuple(field.name for field in fields(SafeResponseValidation))
_RESPONSE_ANSWER_KEYS = tuple(field.name for field in fields(SafeResponseAnswerFacts))
_RESPONSE_QUESTION_SUFFIX = re.compile(r"(?:o[1-6]|effect_[0-7]|completed_claim_present|story_relevance|story_willingness|story_refusal|specific_notice|affect_supported)\Z")
_RESPONSE_NOUL_SUFFIXES = frozenset({"completed_claim_present", "story_relevance",
    "story_willingness", "story_refusal", "specific_notice"})


def _credential_key(value: str) -> bool:
    # JSON decoding handles Unicode escapes; NFKC covers compatibility-width keys.
    # This intentionally does not promise arbitrary homoglyph/encoded-key detection.
    normal = unicodedata.normalize("NFKC", value).casefold()
    compact = "".join(char for char in normal if char.isalnum())
    return (compact in _CREDENTIAL_KEYS or
            any(compact.endswith(key) for key in _CREDENTIAL_KEYS
                if key not in ("headers", "token", "secret", "cookie")) or
            any(part in _CREDENTIAL_KEYS for part in re.split(r"[_\s-]+", normal)))


@dataclass
class _ReviewBudget:
    nodes: int = 0
    chars: int = 0

    def spend(self, *, depth: int, chars: int = 0) -> None:
        self.nodes += 1
        self.chars += chars
        if depth > _MAX_DEPTH or self.nodes > _MAX_NODES or self.chars > _MAX_REVIEW_CHARS:
            raise ValueError("privacy review budget exceeded")


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("ambiguous JSON object")
        result[key] = value
    return result


def _invalid_constant(value):
    raise ValueError("nonfinite JSON value")


_JSON = json.JSONDecoder(object_pairs_hook=_unique_object, parse_constant=_invalid_constant)


def _json_end(value: str, start: int, depth: int) -> int:
    """Bound structural depth before handing untrusted text to the JSON decoder."""
    quoted, escaped, stack = False, False, []
    for index in range(start, len(value)):
        char = value[index]
        if quoted:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
            continue
        if char == '"':
            quoted = True
        elif char in "[{":
            stack.append(char)
            if depth + len(stack) > _MAX_DEPTH:
                raise ValueError("privacy review depth exceeded")
        elif char in "]}":
            if not stack or stack.pop() != ("[" if char == "]" else "{"):
                raise ValueError("malformed JSON structure")
            if not stack:
                return index + 1
    raise ValueError("incomplete JSON structure")


def context_dict(context: DiagnosticContext) -> dict:
    if type(context) is not DiagnosticContext:
        raise ValueError("invalid correlation")
    result = {}
    for key in _CONTEXT_KEYS:
        value = getattr(context, key)
        if value is not None:
            if type(value) is not str or not 1 <= len(value) <= 256:
                raise ValueError("invalid correlation")
            result[key] = correlation_hash(value)
    return result


def _number(value, *, minimum=0, maximum=86400000):
    if type(value) not in (int, float) or not math.isfinite(value) or not minimum <= value <= maximum:
        raise ValueError("invalid numeric field")
    return round(value, 3)


def _bounded_count(value, *, maximum: int, optional: bool = True):
    if value is None and optional:
        return None
    if type(value) is not int or not 0 <= value <= maximum:
        raise ValueError("invalid response diagnostic count")
    return value


def _bounded_range(value, *, maximum: float):
    if value is None:
        return None
    if type(value) is not tuple or len(value) != 2:
        raise ValueError("invalid response diagnostic range")
    lower = _optional_probability(value[0], maximum=maximum)
    upper = _optional_probability(value[1], maximum=maximum)
    if lower is None or upper is None or lower > upper:
        raise ValueError("invalid response diagnostic range")
    return [lower, upper]


def _optional_probability(value, *, maximum: float = 1.0):
    if value is None:
        return None
    if type(value) is int:
        if not 0 <= value <= maximum:
            raise ValueError("invalid response diagnostic probability")
        return float(value)
    if (type(value) is not float or not math.isfinite(value)
            or not 0 <= value <= maximum):
        raise ValueError("invalid response diagnostic probability")
    return value


def _encode_response_answer_facts(value: SafeResponseAnswerFacts) -> dict:
    if type(value) is not SafeResponseAnswerFacts:
        raise ValueError("invalid response answer diagnostics")
    suffix = value.question_suffix
    if type(suffix) is not str or not _RESPONSE_QUESTION_SUFFIX.fullmatch(suffix):
        raise ValueError("invalid response question suffix")
    try:
        wire_type = ResponseWireType(value.answer_wire_type).value
        reason = (ResponseValidationReason(value.answer_reason).value
                  if value.answer_reason is not None else None)
        choice = ResponseChoice(value.choice).value if value.choice is not None else None
    except (TypeError, ValueError):
        raise ValueError("invalid response answer diagnostics") from None
    is_noul = suffix in _RESPONSE_NOUL_SUFFIXES
    if (type(value.expected_probability_count) is not int
            or value.expected_probability_count != (0 if is_noul else 3)):
        raise ValueError("invalid response answer diagnostics")
    if (value.selected_is_maximum is not None and type(value.selected_is_maximum) is not bool
            or value.confidence_consistent is not None and type(value.confidence_consistent) is not bool
            or value.confidence_mismatch_warning is not None
            and type(value.confidence_mismatch_warning) is not bool):
        raise ValueError("invalid response answer diagnostics")
    if (is_noul and (value.choice is not None
                     or value.probability_field_count is not None
                     or value.confidence is not None or value.selected_probability is not None
                     or value.maximum_probability is not None or value.probability_sum is not None
                     or value.selected_is_maximum is not None
                     or value.confidence_consistent is not None
                     or value.confidence_mismatch_warning is not None)):
        raise ValueError("invalid response answer diagnostics")
    if not is_noul and value.noul_probability is not None:
        raise ValueError("invalid response answer diagnostics")
    result = {
        "question_suffix": suffix,
        "answer_wire_type": wire_type,
        "answer_reason": reason,
        "choice": choice,
        "answer_field_count": _bounded_count(value.answer_field_count, maximum=64),
        "unexpected_answer_field_count": _bounded_count(
            value.unexpected_answer_field_count, maximum=64),
        "expected_probability_count": value.expected_probability_count,
        "probability_field_count": _bounded_count(value.probability_field_count, maximum=64),
        "unexpected_probability_field_count": _bounded_count(
            value.unexpected_probability_field_count, maximum=64),
        "valid_probability_count": _bounded_count(value.valid_probability_count, maximum=3,
                                                    optional=False),
        "confidence": _optional_probability(value.confidence),
        "selected_probability": _optional_probability(value.selected_probability),
        "maximum_probability": _optional_probability(value.maximum_probability),
        "probability_sum": _optional_probability(value.probability_sum, maximum=3),
        "selected_is_maximum": value.selected_is_maximum,
        "confidence_consistent": value.confidence_consistent,
    }
    if is_noul:
        result["noul_probability"] = _optional_probability(value.noul_probability)
    if value.confidence_mismatch_warning is not None:
        result["confidence_mismatch_warning"] = value.confidence_mismatch_warning
    return result


def _encode_response_validation(value: SafeResponseValidation) -> dict:
    if type(value) is not SafeResponseValidation:
        raise ValueError("invalid response diagnostics")
    try:
        reason = ResponseValidationReason(value.parser_reason).value
        wire_type = ResponseWireType(value.response_wire_type).value
    except (TypeError, ValueError):
        raise ValueError("invalid response diagnostics") from None
    response_bytes = _bounded_count(value.response_bytes, maximum=64 * 1024 + 1)
    expected = _bounded_count(value.expected_answer_count, maximum=20)
    answer_count = _bounded_count(value.answer_count, maximum=64)
    missing = _bounded_count(value.missing_answer_count, maximum=20)
    unexpected = _bounded_count(value.unexpected_answer_count, maximum=64)
    invalid = _bounded_count(value.invalid_answer_count, maximum=20)
    invalid_probabilities = _bounded_count(value.invalid_probability_count, maximum=20)
    nonfinite = _bounded_count(value.nonfinite_numeric_count, maximum=64)
    oversized = _bounded_count(value.oversized_integer_count, maximum=64)
    digest = value.response_sha256
    if digest is not None and (type(digest) is not str or not re.fullmatch(r"[0-9a-f]{64}", digest)):
        raise ValueError("invalid response diagnostics")
    if type(value.answer_facts) is not tuple or len(value.answer_facts) > 20:
        raise ValueError("invalid response answer diagnostics")
    answer_facts = [_encode_response_answer_facts(item) for item in value.answer_facts]
    suffixes = [item["question_suffix"] for item in answer_facts]
    if len(suffixes) != len(set(suffixes)):
        raise ValueError("duplicate response question suffix")
    if expected is not None and len(answer_facts) != expected:
        raise ValueError("response answer diagnostic count mismatch")
    result = {
        "parser_reason": reason, "response_wire_type": wire_type,
        "response_bytes": response_bytes, "response_sha256": digest,
        "expected_answer_count": expected, "answer_count": answer_count,
        "missing_answer_count": missing, "unexpected_answer_count": unexpected,
        "invalid_answer_count": invalid, "invalid_probability_count": invalid_probabilities,
        "nonfinite_numeric_count": nonfinite, "oversized_integer_count": oversized,
        "selected_probability_range": _bounded_range(value.selected_probability_range, maximum=1),
        "confidence_range": _bounded_range(value.confidence_range, maximum=1),
        "probability_sum_range": _bounded_range(value.probability_sum_range, maximum=3),
        "answer_facts": answer_facts,
    }
    if value.choice_wire_policy_version is not None:
        if value.choice_wire_policy_version not in SUPPORTED_CHOICE_WIRE_POLICIES:
            raise ValueError("invalid response choice wire policy")
        if (value.choice_wire_policy_version == CHOICE_WIRE_POLICY_REPORTED_V2
                and any(("confidence_mismatch_warning" in item)
                         if item["question_suffix"] in _RESPONSE_NOUL_SUFFIXES else
                         item.get("confidence_mismatch_warning") not in (True, False)
                        for item in answer_facts)):
            raise ValueError("invalid reported-confidence warning facts")
        result["choice_wire_policy_version"] = value.choice_wire_policy_version
    return result


def _encode_reported_confidence_warning(value: ReportedConfidenceWarning) -> dict:
    if (type(value) is not ReportedConfidenceWarning
            or value.choice_wire_policy_version != CHOICE_WIRE_POLICY_REPORTED_V2):
        raise ValueError("invalid reported-confidence warning")
    maximum = _optional_probability(value.maximum_probability)
    confidence = _optional_probability(value.confidence)
    probability_sum = _optional_probability(value.probability_sum, maximum=3)
    if maximum is None or confidence is None or probability_sum is None:
        raise ValueError("invalid reported-confidence warning")
    return {"choice_wire_policy_version": CHOICE_WIRE_POLICY_REPORTED_V2,
            "maximum_probability": maximum, "confidence": confidence,
            "probability_sum": probability_sum}


def _reported_confidence_warning_from_record(value) -> ReportedConfidenceWarning:
    if type(value) is not dict or set(value) != {
            "choice_wire_policy_version", "maximum_probability", "confidence", "probability_sum"}:
        raise ValueError("invalid reported-confidence warning")
    try:
        warning = ReportedConfidenceWarning(**value)
    except (TypeError, ValueError):
        raise ValueError("invalid reported-confidence warning") from None
    _encode_reported_confidence_warning(warning)
    return warning


def _response_answer_facts_from_record(value) -> tuple[SafeResponseAnswerFacts, ...]:
    if type(value) is not list or len(value) > 20:
        raise ValueError("invalid response answer diagnostics")
    result = []
    for item in value:
        legacy_keys = set(_RESPONSE_ANSWER_KEYS) - {"noul_probability", "confidence_mismatch_warning"}
        no_warning_keys = set(_RESPONSE_ANSWER_KEYS) - {"confidence_mismatch_warning"}
        if type(item) is not dict or set(item) not in (
                set(_RESPONSE_ANSWER_KEYS), legacy_keys, no_warning_keys):
            raise ValueError("invalid response answer diagnostics")
        converted = dict(item)
        try:
            converted["answer_wire_type"] = ResponseWireType(converted["answer_wire_type"])
            if converted["answer_reason"] is not None:
                converted["answer_reason"] = ResponseValidationReason(converted["answer_reason"])
            if converted["choice"] is not None:
                converted["choice"] = ResponseChoice(converted["choice"])
            answer = SafeResponseAnswerFacts(**converted)
        except (TypeError, ValueError):
            raise ValueError("invalid response answer diagnostics") from None
        _encode_response_answer_facts(answer)
        result.append(answer)
    suffixes = [item.question_suffix for item in result]
    if len(suffixes) != len(set(suffixes)):
        raise ValueError("duplicate response question suffix")
    return tuple(result)


def _response_validation_from_record(value) -> SafeResponseValidation:
    legacy_keys = set(_RESPONSE_VALIDATION_KEYS) - {"choice_wire_policy_version"}
    if type(value) is not dict or set(value) not in (set(_RESPONSE_VALIDATION_KEYS), legacy_keys):
        raise ValueError("invalid response diagnostics")
    converted = dict(value)
    for key in ("selected_probability_range", "confidence_range", "probability_sum_range"):
        item = converted[key]
        if item is not None:
            if type(item) is not list or len(item) != 2:
                raise ValueError("invalid response diagnostic range")
            # Serializer checks bounds, exact numeric types and finiteness.
            converted[key] = tuple(item)
    converted["answer_facts"] = _response_answer_facts_from_record(converted["answer_facts"])
    try:
        checked = SafeResponseValidation(**converted)
    except (TypeError, ValueError):
        raise ValueError("invalid response diagnostics") from None
    _encode_response_validation(checked)
    return checked


def encode_event(event: DiagnosticEvent, now: float) -> dict:
    if type(event) is not DiagnosticEvent:
        raise ValueError("invalid event")
    result = {"schema": 1, "record_type": "event", "timestamp": _number(now, maximum=1e12),
              "stage": DiagnosticStage(event.stage).value,
              "kind": DiagnosticKind(event.kind).value,
              "outcome": DiagnosticOutcome(event.outcome).value,
              "context": context_dict(event.context)}
    if event.code is not None:
        result["code"] = DiagnosticCode(event.code).value
    if event.cancellation_reason is not None:
        if event.outcome != DiagnosticOutcome.CANCELLED:
            raise ValueError("cancellation reason requires cancelled outcome")
        result["cancellation_reason"] = CancellationReason(event.cancellation_reason).value
    if event.duration_ms is not None:
        result["duration_ms"] = _number(event.duration_ms)
    if event.http_status is not None:
        if type(event.http_status) is not int or not 100 <= event.http_status <= 599:
            raise ValueError("invalid status")
        result["http_status"] = event.http_status
    if event.response_validation is not None:
        result["response_validation"] = _encode_response_validation(event.response_validation)
    if event.reported_confidence_warning is not None:
        if (DiagnosticStage(event.stage) != DiagnosticStage.INPUT_REVIEW
                or DiagnosticOutcome(event.outcome) not in
                (DiagnosticOutcome.SUCCEEDED, DiagnosticOutcome.FAILED)):
            raise ValueError("reported-confidence warning requires input review event")
        result["reported_confidence_warning"] = _encode_reported_confidence_warning(
            event.reported_confidence_warning)
    return result


def validate_event_record(record: dict) -> dict:
    required = {"schema", "record_type", "timestamp", "stage", "kind", "outcome", "context"}
    optional = {"code", "cancellation_reason", "duration_ms", "http_status",
                "response_validation", "reported_confidence_warning"}
    if (type(record) is not dict or not required <= record.keys()
            or record.keys() - required - optional or type(record["schema"]) is not int
            or record["schema"] != 1 or record["record_type"] != "event"):
        raise ValueError("invalid event schema")
    context = record["context"]
    if (type(context) is not dict or context.keys() - set(_CONTEXT_KEYS)
            or any(type(value) is not str or not _HASH.fullmatch(value) for value in context.values())):
        raise ValueError("invalid correlation")
    response_validation = (_response_validation_from_record(record["response_validation"])
                           if "response_validation" in record else None)
    reported_confidence_warning = (
        _reported_confidence_warning_from_record(record["reported_confidence_warning"])
        if "reported_confidence_warning" in record else None)
    event = DiagnosticEvent(stage=record["stage"], kind=record["kind"], outcome=record["outcome"],
        code=record.get("code"), cancellation_reason=record.get("cancellation_reason"),
        duration_ms=record.get("duration_ms"), http_status=record.get("http_status"),
        response_validation=response_validation,
        reported_confidence_warning=reported_confidence_warning)
    checked = encode_event(event, record["timestamp"])
    checked["context"] = dict(context)
    return checked


class PrivacyFilter:
    """Trusted injection of active secrets; repr never exposes them.

    Pattern checks are a second defense. Exact-record privacy review is still
    mandatory, especially for audio and unknown credential formats.
    """
    def __init__(self, secrets=()):
        self._secrets: tuple[str, ...] = ()
        for value in secrets:
            self.add_secret(value)

    def add_secret(self, value: str) -> None:
        if type(value) is not str or not value or len(value) > 8192:
            raise ValueError("invalid trusted secret")
        if value in self._secrets:
            return
        if len(self._secrets) >= 4096:
            raise ValueError("trusted secret budget reached")
        self._secrets += (value,)

    def text(self, value: str) -> str:
        if (type(value) is not str or len(value) > _MAX_TEXT_BYTES
                or len(value.encode()) > _MAX_TEXT_BYTES):
            raise ValueError("invalid text buffer")
        result = self._text(value, _ReviewBudget(), 0)
        if len(result) > _MAX_TEXT_BYTES or len(result.encode()) > _MAX_TEXT_BYTES:
            raise ValueError("filtered text exceeds budget")
        return result

    def _plain(self, value: str) -> str:
        normalized = unicodedata.normalize("NFKC", value)
        if (_FORBIDDEN_ENVELOPE.search(normalized) or any(
                _credential_key(match.group(1)) for match in _QUOTED_ASSIGNMENT.finditer(normalized))):
            raise ValueError("credential envelope is ineligible")
        for secret in sorted(self._secrets, key=len, reverse=True):
            value = value.replace(secret, "[REDACTED]")
        for pattern in _SECRET_SHAPES:
            value = pattern.sub("[REDACTED]", value)
        # Escaped syntax outside valid JSON is uncertain, never guessed/decoded.
        if _NON_JSON_ESCAPE.search(value):
            raise ValueError("ambiguous non-JSON escape")
        return value

    def _walk(self, value, budget: _ReviewBudget, depth: int):
        budget.spend(depth=depth)
        if type(value) is str:
            return self._text(value, budget, depth + 1)
        if type(value) is list:
            return [self._walk(item, budget, depth + 1) for item in value]
        if type(value) is dict:
            result = {}
            for key, item in value.items():
                budget.spend(depth=depth + 1, chars=len(key))
                if _credential_key(key):
                    raise ValueError("credential envelope is ineligible")
                safe_key = self._text(key, budget, depth + 1)
                if safe_key in result:
                    raise ValueError("ambiguous filtered JSON object")
                result[safe_key] = self._walk(item, budget, depth + 1)
            return result
        if value is None or type(value) in (bool, int):
            return value
        if type(value) is float and math.isfinite(value):
            return value
        raise ValueError("invalid JSON value")

    def _text(self, value: str, budget: _ReviewBudget, depth: int) -> str:
        budget.spend(depth=depth, chars=len(value))
        stripped = value.lstrip()
        if stripped and stripped[0] in '{["' and not stripped.startswith("[REDACTED]"):
            if stripped[0] in "{[":
                _json_end(stripped, 0, depth)
            parsed, end = _JSON.raw_decode(stripped)
            if stripped[end:].strip():
                raise ValueError("ambiguous JSON suffix")
            checked = self._walk(parsed, budget, depth + 1)
            return (value if checked == parsed else
                    json.dumps(checked, ensure_ascii=False, allow_nan=False))
        value = self._plain(value)
        # A JSON envelope embedded in prose still receives the same review. Invalid
        # bracket/brace fragments are dropped conservatively rather than decoded.
        pieces, cursor = [], 0
        while cursor < len(value):
            match = _JSON_START.search(value, cursor)
            if match is None:
                break
            start = match.start()
            pieces.append(value[cursor:start])
            if value.startswith("[REDACTED]", start):
                pieces.append("[REDACTED]")
                cursor = start + len("[REDACTED]")
                continue
            end = _json_end(value, start, depth)
            parsed, decoded_end = _JSON.raw_decode(value, start)
            if end != decoded_end:
                raise ValueError("ambiguous JSON fragment")
            checked = self._walk(parsed, budget, depth + 1)
            pieces.append(value[start:end] if checked == parsed else
                          json.dumps(checked, ensure_ascii=False, allow_nan=False))
            cursor = end
        pieces.append(value[cursor:])
        return "".join(pieces)

    def recording(self, record: ReviewedRecording, *, now: float,
                  max_text_bytes: int, max_audio_bytes: int) -> dict:
        if (type(record) is not ReviewedRecording
                or record.review not in (ContentReview.APPROVED, ContentReview.REDACTED)):
            raise ValueError("privacy review required")
        kind = RecordingKind(record.kind)
        result = {"schema": 1, "record_type": "reviewed_raw",
                  "timestamp": _number(now, maximum=1e12), "kind": kind.value,
                  "privacy_review": ContentReview(record.review).value,
                  "context": context_dict(record.context)}
        if kind in (RecordingKind.DIALOGUE, RecordingKind.MODEL_INPUT, RecordingKind.MODEL_OUTPUT):
            if (type(record.text) is not str or record.audio is not None
                    or record.sample_rate_hz is not None
                    or len(record.text) > max_text_bytes
                    or len(record.text.encode()) > max_text_bytes):
                raise ValueError("invalid text buffer")
            result["text"] = self.text(record.text)
            if result["text"] != record.text:
                result["privacy_review"] = ContentReview.REDACTED.value
        else:
            if (type(record.audio) is not bytes or record.text is not None
                    or not record.audio or len(record.audio) % 2
                    or len(record.audio) > max_audio_bytes
                    or type(record.sample_rate_hz) is not int
                    or record.sample_rate_hz not in (16000, 24000, 48000)):
                raise ValueError("invalid audio buffer")
            # A known credential embedded as bytes is also forbidden. This is not
            # spoken-secret detection; approval must cover listening/privacy review.
            if any(secret.encode() in record.audio for secret in self._secrets):
                raise ValueError("credential bytes")
            ascii_view = record.audio.decode("ascii", errors="ignore")
            if _FORBIDDEN_ENVELOPE.search(ascii_view) or any(
                    pattern.search(ascii_view) for pattern in _SECRET_SHAPES):
                raise ValueError("credential bytes")
            result["audio_base64"] = base64.b64encode(record.audio).decode("ascii")
            result["sample_rate_hz"] = record.sample_rate_hz
        return result


def validate_raw_record(record: dict) -> dict:
    required = {"schema", "record_type", "timestamp", "kind", "privacy_review", "context"}
    if (type(record) is not dict or not required <= record.keys()
            or record.keys() - required - {"text", "audio_base64", "sample_rate_hz"}
            or type(record["schema"]) is not int or record["schema"] != 1
            or record["record_type"] != "reviewed_raw"):
        raise ValueError("invalid recording schema")
    context = record["context"]
    if (type(context) is not dict or context.keys() - set(_CONTEXT_KEYS)
            or any(type(value) is not str or not _HASH.fullmatch(value) for value in context.values())):
        raise ValueError("invalid correlation")
    audio = None
    if "audio_base64" in record:
        audio = base64.b64decode(record["audio_base64"], validate=True)
    checked = PrivacyFilter().recording(ReviewedRecording(kind=record["kind"],
        review=record["privacy_review"], text=record.get("text"), audio=audio,
        sample_rate_hz=record.get("sample_rate_hz")), now=record["timestamp"],
        max_text_bytes=128 * 1024, max_audio_bytes=512 * 1024)
    checked["context"] = dict(context)
    return checked

"""Provider-direct OpenAI Responses transports for MIRA candidate generation.

Both supported routes are fixed endpoints selected explicitly by the caller. The
ChatGPT Codex subscription endpoint is an undocumented/private compatibility target;
this module makes no claim that it is a public OpenAI API contract. Credentials are
injected as opaque SecretStr values, and all provider output remains an untrusted
candidate until the existing independent review/application path accepts it.
"""
from __future__ import annotations

import asyncio
import json
import math
import re
import uuid
from collections.abc import AsyncIterator
from dataclasses import dataclass
from enum import StrEnum
from typing import Protocol

import httpx

from mira.application.contracts import CandidateRange, GenerationContext
from mira.domain.errors import DomainError

from .codex_support.payload import author_instructions, build_prompt, strict_json
from .codex_support.character_payload import parse_character_candidate

SUBSCRIPTION_ENDPOINT = "https://chatgpt.com/backend-api/codex/responses"
OPENAI_API_ENDPOINT = "https://api.openai.com/v1/responses"
_MODEL_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}\Z")
_SAFE_HEADER_VALUE = re.compile(r"[\x21-\x7e]{1,256}\Z")
_MIME_TOKEN = r"[!#$%&'*+\-.^_`|~0-9A-Za-z]+"
_MIME_QUOTED_VALUE = r'"(?:[\t\x20-\x21\x23-\x5b\x5d-\x7e]|\\[\t\x20-\x7e])*"'
_SSE_CONTENT_TYPE = re.compile(
    rf"\A[ \t]*text/event-stream[ \t]*(?:;[ \t]*{_MIME_TOKEN}[ \t]*=[ \t]*"
    rf"(?:{_MIME_TOKEN}|{_MIME_QUOTED_VALUE})[ \t]*)*\Z", re.IGNORECASE | re.ASCII)
_TOOL_ITEM_TYPES = frozenset({
    "function_call", "computer_call", "web_search_call", "file_search_call",
    "mcp_call", "code_interpreter_call", "image_generation_call", "shell_call",
})


class ResponsesRoute(StrEnum):
    """Explicit route selection; each value resolves only to a hard-coded endpoint."""

    CHATGPT_SUBSCRIPTION = "chatgpt_subscription"
    OPENAI_API = "openai_api"


class SecretToken(Protocol):
    """Small structural view of pydantic.SecretStr; never stringify a credential."""

    def get_secret_value(self) -> str: ...


class CredentialRecord(Protocol):
    access_token: SecretToken
    account_id: str | None
    residency: str | None


class CodexCredentialSource(Protocol):
    """Auth owner supplies credentials; the generation adapter never opens auth storage."""

    async def get_credentials(self) -> CredentialRecord: ...


@dataclass(frozen=True, slots=True)
class DirectResponsesLimits:
    startup_seconds: float = 10.0
    turn_seconds: float = 60.0
    max_line_bytes: int = 131_072
    max_wire_bytes: int = 1_048_576
    max_request_bytes: int = 131_072
    max_output_bytes: int = 16_384
    max_prompt_bytes: int = 65_536
    max_events: int = 1_024

    def __post_init__(self) -> None:
        for value in (self.startup_seconds, self.turn_seconds):
            if (type(value) not in (int, float) or not math.isfinite(value)
                    or not 0 < value <= 120):
                raise ValueError("direct_responses_timeout_limit_invalid")
        bounds = (
            (self.max_line_bytes, 128, 262_144),
            (self.max_wire_bytes, 1_024, 4_194_304),
            (self.max_request_bytes, 1_024, 262_144),
            (self.max_output_bytes, 128, 65_536),
            (self.max_prompt_bytes, 1_024, 131_072),
            (self.max_events, 1, 4_096),
        )
        if any(type(value) is not int or not low <= value <= high
               for value, low, high in bounds):
            raise ValueError("direct_responses_size_limit_invalid")


class DirectResponsesError(DomainError):
    """Fixed safe code plus local stage/status; never contains provider strings."""

    def __init__(self, code: str, stage: str, *, http_status: int | None = None) -> None:
        super().__init__(code, code)
        self.stage = stage
        self.http_status = http_status


@dataclass(frozen=True, slots=True)
class _SSEEvent:
    name: str
    data: str


@dataclass(frozen=True, slots=True)
class _CompletedOutput:
    output_index: int
    item_id: str | None
    text: str


def _payload_error_code(error: RuntimeError) -> str | None:
    """Recognize only fixed local payload/parser codes; never stringify error objects."""
    try:
        args = error.args
    except Exception:
        return None
    if len(args) == 1 and type(args[0]) is str and args[0] in {
            "codex_prompt_limit", "codex_context_invalid", "codex_capability_invalid",
            "codex_output_limit", "codex_json_invalid", "codex_effects_invalid",
            "codex_effects_unsupported"}:
        return args[0]
    return None


class DirectCodexResponsesGenerationBackend:
    """Default-OFF, bounded provider-direct `GenerationBackend` implementation.

    `transport` is an optional HTTPX transport injection for offline tests. Omit it for
    the normal HTTPX client, which keeps TLS verification and the environment's default
    proxy/network policy. Redirects are always disabled and the destination is fixed.
    """

    def __init__(self, route: ResponsesRoute, model: str,
                 credential_source: CodexCredentialSource, *, admitted: bool = False,
                 request_limit: int = 0, limits: DirectResponsesLimits | None = None,
                 transport: httpx.AsyncBaseTransport | None = None,
                 speech_enabled: bool = True) -> None:
        if type(route) is not ResponsesRoute:
            raise ValueError("direct_responses_route_invalid")
        if type(model) is not str or not _MODEL_PATTERN.fullmatch(model):
            raise ValueError("direct_responses_model_invalid")
        if (credential_source is None
                or not callable(getattr(credential_source, "get_credentials", None))):
            raise ValueError("direct_responses_credentials_unavailable")
        if type(admitted) is not bool or type(speech_enabled) is not bool:
            raise ValueError("direct_responses_admission_invalid")
        if type(request_limit) is not int or not 0 <= request_limit <= 100:
            raise ValueError("direct_responses_request_limit_invalid")
        if limits is not None and type(limits) is not DirectResponsesLimits:
            raise ValueError("direct_responses_limits_invalid")
        if transport is not None and not isinstance(transport, httpx.AsyncBaseTransport):
            raise ValueError("direct_responses_transport_invalid")
        self._route = route
        self._endpoint = (SUBSCRIPTION_ENDPOINT if route is ResponsesRoute.CHATGPT_SUBSCRIPTION
                          else OPENAI_API_ENDPOINT)
        self._model = model
        self._credential_source = credential_source
        self._admitted = admitted
        self._remaining = request_limit
        self._limits = limits or DirectResponsesLimits()
        self._transport = transport
        self._speech_enabled = speech_enabled

    async def generate(self, context: GenerationContext) -> AsyncIterator[CandidateRange]:
        if not self._admitted:
            raise DirectResponsesError("blocked", "admission")
        if not self._remaining:
            raise DirectResponsesError("response_limit", "admission")

        try:
            prompt = build_prompt(context, self._limits, speech_enabled=self._speech_enabled)
        except RuntimeError as error:
            code = _payload_error_code(error)
            mapped = "input_limit" if code == "codex_prompt_limit" else "invalid_input"
            raise DirectResponsesError(mapped, "prompt") from None
        except Exception:
            raise DirectResponsesError("invalid_input", "prompt") from None

        body = {
            "model": self._model,
            "instructions": author_instructions(
                speech_enabled=self._speech_enabled,
                memory_enabled=context.memory_packet is not None,
                character_story_enabled=context.character_story is not None,
            ),
            "input": [{"role": "user", "content": [{"type": "input_text", "text": prompt}]}],
            "store": False,
            "stream": True,
        }
        try:
            request_body = json.dumps(body, ensure_ascii=False, separators=(",", ":"),
                                      allow_nan=False).encode("utf-8")
        except (TypeError, ValueError, UnicodeError, RecursionError):
            raise DirectResponsesError("invalid_input", "request") from None
        if len(request_body) > self._limits.max_request_bytes:
            raise DirectResponsesError("input_limit", "request")

        # Reserve before the first await; every attempt, including auth/transport errors,
        # consumes one admitted request. There is deliberately no retry or route fallback.
        self._remaining -= 1
        try:
            async with asyncio.timeout(self._limits.startup_seconds):
                credentials = await self._credential_source.get_credentials()
                headers = self._headers(credentials)
        except asyncio.CancelledError:
            raise
        except TimeoutError:
            raise DirectResponsesError("timeout", "credentials") from None
        except DirectResponsesError:
            raise
        except Exception:
            raise DirectResponsesError("unauthenticated", "credentials") from None

        candidates: tuple | None = None
        client_timeout = httpx.Timeout(
            connect=self._limits.startup_seconds,
            read=self._limits.turn_seconds,
            write=self._limits.startup_seconds,
            pool=self._limits.startup_seconds,
        )
        try:
            async with httpx.AsyncClient(
                    transport=self._transport, follow_redirects=False,
                    timeout=client_timeout, headers={"Accept-Encoding": "identity"}) as client:
                async with asyncio.timeout(self._limits.turn_seconds):
                    async with client.stream(
                            "POST", self._endpoint, content=request_body,
                            headers=headers) as response:
                        self._check_status(response)
                        self._check_content_length(response)
                        if not _SSE_CONTENT_TYPE.fullmatch(
                                response.headers.get("content-type", "")):
                            raise DirectResponsesError("invalid_response", "response_headers",
                                                       http_status=response.status_code)
                        assembler = _ResponseAssembler(self._limits)
                        async for event in _iter_sse_events(response, self._limits):
                            assembler.consume(event)
                        texts = assembler.finish()
                        try:
                            candidates,story_proposal,affect_proposal = parse_character_candidate(
                                texts,self._limits,context,speech_enabled=self._speech_enabled)
                        except RuntimeError as error:
                            code = _payload_error_code(error)
                            mapped = ("output_limit" if code == "codex_output_limit"
                                      else "invalid_response")
                            raise DirectResponsesError(mapped, "validation") from None
        except asyncio.CancelledError:
            raise
        except DirectResponsesError:
            raise
        except (TimeoutError, httpx.TimeoutException):
            raise DirectResponsesError("timeout", "stream") from None
        except httpx.HTTPStatusError as error:
            # Status is known and safe. The provider body and headers are not retained.
            raise DirectResponsesError("unavailable", "http_status",
                                       http_status=error.response.status_code) from None
        except httpx.HTTPError:
            raise DirectResponsesError("unavailable", "transport") from None
        except (UnicodeError, json.JSONDecodeError):
            raise DirectResponsesError("invalid_response", "sse") from None
        except Exception:
            # Never stringify network exceptions: they may include request details.
            raise DirectResponsesError("unavailable", "transport") from None

        assert candidates is not None
        yield CandidateRange(candidates, f"direct-codex-responses-origin:{uuid.uuid4().hex}",
                             story_proposal,affect_proposal)

    def _headers(self, credentials: CredentialRecord) -> dict[str, str]:
        if credentials is None:
            raise DirectResponsesError("unauthenticated", "credentials")
        secret = getattr(credentials, "access_token", None)
        getter = getattr(secret, "get_secret_value", None)
        if not callable(getter):
            raise DirectResponsesError("unauthenticated", "credentials")
        try:
            token = getter()
        except Exception:
            raise DirectResponsesError("unauthenticated", "credentials") from None
        if (type(token) is not str or not token
                or any(ord(char) < 33 or ord(char) > 126 for char in token)):
            raise DirectResponsesError("unauthenticated", "credentials")

        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
            "Accept": "text/event-stream",
            "Originator": "mira",
            "User-Agent": "MIRA/0.4.1",
        }
        if self._route is ResponsesRoute.CHATGPT_SUBSCRIPTION:
            account_id = getattr(credentials, "account_id", None)
            residency = getattr(credentials, "residency", None)
            if account_id is not None:
                if type(account_id) is not str or not _SAFE_HEADER_VALUE.fullmatch(account_id):
                    raise DirectResponsesError("unauthenticated", "credentials")
                headers["ChatGPT-Account-ID"] = account_id
            if residency is not None:
                if type(residency) is not str or not _SAFE_HEADER_VALUE.fullmatch(residency):
                    raise DirectResponsesError("unauthenticated", "credentials")
                headers["x-openai-internal-codex-residency"] = residency
        return headers

    @staticmethod
    def _check_status(response: httpx.Response) -> None:
        status = response.status_code
        if status < 300:
            return
        if status == 401:
            code, stage = "unauthenticated", "auth"
        elif status == 403:
            code, stage = "permission_denied", "authorization"
        elif status == 429:
            code, stage = "quota_exhausted", "quota"
        elif status in (408, 504):
            code, stage = "timeout", "http_status"
        elif status in (400, 422):
            code, stage = "invalid_input", "http_status"
        elif 300 <= status < 400:
            code, stage = "unavailable", "redirect"
        elif status >= 500:
            code, stage = "unavailable", "http_status"
        else:
            code, stage = "invalid_response", "http_status"
        raise DirectResponsesError(code, stage, http_status=status)

    def _check_content_length(self, response: httpx.Response) -> None:
        raw = response.headers.get("content-length")
        if raw is None:
            return
        if not raw.isdecimal():
            raise DirectResponsesError("invalid_response", "response_headers",
                                       http_status=response.status_code)
        if int(raw) > self._limits.max_wire_bytes:
            raise DirectResponsesError("response_limit", "sse",
                                       http_status=response.status_code)


async def _iter_sse_events(response: httpx.Response,
                           limits: DirectResponsesLimits) -> AsyncIterator[_SSEEvent]:
    """Incrementally decode bounded UTF-8 SSE records, including CR/LF and multiline data."""
    pending = bytearray()
    data_lines: list[str] = []
    event_name = ""
    event_count = 0
    wire_bytes = 0
    first_line = True

    def process_line(raw: bytes) -> None:
        nonlocal event_name, first_line
        if len(raw) > limits.max_line_bytes:
            raise DirectResponsesError("response_limit", "sse")
        try:
            line = raw.decode("utf-8", errors="strict")
        except UnicodeDecodeError:
            raise DirectResponsesError("invalid_response", "sse") from None
        if first_line:
            first_line = False
            if line.startswith("\ufeff"):
                line = line[1:]
        if not line:
            return
        if line.startswith(":"):
            return
        field, separator, value = line.partition(":")
        if not separator:
            value = ""
        elif value.startswith(" "):
            value = value[1:]
        if field == "data":
            data_lines.append(value)
        elif field == "event":
            # Event names are opaque until dispatch; the line bound constrains storage.
            event_name = value

    def dispatch() -> _SSEEvent | None:
        nonlocal event_name, event_count, data_lines
        if not data_lines and not event_name:
            return None
        event_count += 1
        if event_count > limits.max_events:
            raise DirectResponsesError("response_limit", "sse")
        event = _SSEEvent(event_name, "\n".join(data_lines))
        event_name = ""
        data_lines = []
        return event

    async for chunk in response.aiter_raw():
        wire_bytes += len(chunk)
        if wire_bytes > limits.max_wire_bytes:
            raise DirectResponsesError("response_limit", "sse")
        pending.extend(chunk)
        while True:
            lf = pending.find(b"\n")
            cr = pending.find(b"\r")
            separators = [index for index in (lf, cr) if index >= 0]
            if not separators:
                if len(pending) > limits.max_line_bytes:
                    raise DirectResponsesError("response_limit", "sse")
                break
            index = min(separators)
            if pending[index] == 13 and index == len(pending) - 1:
                if index > limits.max_line_bytes:
                    raise DirectResponsesError("response_limit", "sse")
                break
            raw_line = bytes(pending[:index])
            delim_size = 2 if pending[index] == 13 and pending[index + 1] == 10 else 1
            del pending[:index + delim_size]
            process_line(raw_line)
            if not raw_line:
                emitted = dispatch()
                if emitted is not None:
                    yield emitted

    if pending:
        if pending.endswith(b"\r"):
            raw_line = bytes(pending[:-1])
        else:
            raw_line = bytes(pending)
        process_line(raw_line)
        pending.clear()
    if data_lines or event_name:
        emitted = dispatch()
        if emitted is not None:
            yield emitted


class _ResponseAssembler:
    """Private bounded state: done message items win; deltas are fallback only."""

    _JSON_EVENT_NAMES = frozenset({
        "response.output_item.done", "response.output_item.added",
        "response.output_text.delta", "response.completed", "response.failed",
        "response.incomplete", "response.cancelled", "response.canceled",
        "response.error", "error",
    })
    _FAILURE_EVENTS = frozenset({"response.failed", "response.error", "error"})
    _INCOMPLETE_EVENTS = frozenset({
        "response.incomplete", "response.cancelled", "response.canceled",
    })

    def __init__(self, limits: DirectResponsesLimits) -> None:
        self._limits = limits
        self._completed: dict[int, _CompletedOutput] = {}
        self._deltas: dict[int, dict[int, str]] = {}
        self._delta_ids: dict[int, str] = {}
        self._terminal = False
        self._failed = False
        self._done_sentinel_seen = False

    def consume(self, sse: _SSEEvent) -> None:
        if self._done_sentinel_seen:
            raise DirectResponsesError("invalid_response", "terminal")
        if not sse.name and sse.data == "[DONE]":
            if not self._terminal:
                raise DirectResponsesError("invalid_response", "terminal")
            self._done_sentinel_seen = True
            return
        kind = sse.name
        obj: object | None = None
        if kind in self._JSON_EVENT_NAMES or not kind:
            try:
                obj = strict_json(sse.data)
            except RuntimeError:
                # Unknown named metadata events are opaque and deliberately discarded.
                if kind and kind not in self._JSON_EVENT_NAMES:
                    return
                raise DirectResponsesError("invalid_response", "sse") from None
            if not kind:
                if type(obj) is not dict or type(obj.get("type")) is not str:
                    return
                kind = obj["type"]
            if kind not in self._JSON_EVENT_NAMES and kind not in (
                    "response.created", "response.in_progress", "response.queued",
                    "response.output_text.done", "response.content_part.added",
                    "response.content_part.done", "response.refusal.delta",
                    "response.refusal.done", "response.reasoning_summary_text.delta",
                    "response.reasoning_summary_text.done", "response.reasoning_text.delta",
                    "response.reasoning_text.done", "response.output_text.annotation.added"):
                # Future event types may carry benign metadata. Count/bytes stay bounded,
                # and no event is allowed to create a candidate without a known text event.
                return
        else:
            # Opaque named events do not need a JSON shape and are safely discarded.
            return

        if type(obj) is not dict:
            raise DirectResponsesError("invalid_response", "sse")
        data_type = obj.get("type")
        if type(data_type) is str and kind in self._JSON_EVENT_NAMES and data_type != kind:
            raise DirectResponsesError("invalid_response", "sse")
        if self._terminal and kind in (
                "response.output_item.added", "response.output_item.done",
                "response.output_text.delta", "response.completed", "response.failed",
                "response.incomplete", "response.cancelled", "response.canceled",
                "response.error", "error"):
            raise DirectResponsesError("invalid_response", "terminal")
        if kind in self._FAILURE_EVENTS:
            self._failed = True
            raise DirectResponsesError("unavailable", "provider")
        if kind in self._INCOMPLETE_EVENTS:
            self._failed = True
            raise DirectResponsesError("invalid_response", "terminal")
        if kind == "response.output_item.added":
            item = obj.get("item")
            if type(item) is dict and item.get("type") in _TOOL_ITEM_TYPES:
                raise DirectResponsesError("invalid_response", "tool_forbidden")
            return
        if kind == "response.output_text.delta":
            self._consume_delta(obj)
            return
        if kind == "response.output_item.done":
            self._consume_completed_item(obj)
            return
        if kind == "response.completed":
            if self._terminal:
                raise DirectResponsesError("invalid_response", "terminal")
            response_data = obj.get("response")
            if type(response_data) is not dict:
                raise DirectResponsesError("invalid_response", "terminal")
            status = response_data.get("status")
            if status in ("failed", "error"):
                raise DirectResponsesError("unavailable", "provider")
            if status == "incomplete":
                raise DirectResponsesError("invalid_response", "terminal")
            if status not in (None, "completed"):
                raise DirectResponsesError("invalid_response", "terminal")
            if response_data.get("error") is not None:
                raise DirectResponsesError("unavailable", "provider")
            if response_data.get("output") is not None:
                snapshot_text = self._terminal_snapshot_text(response_data["output"])
                if snapshot_text != self._assembled_candidate_text():
                    raise DirectResponsesError("invalid_response", "terminal_output")
            self._terminal = True
            return

    def _consume_delta(self, obj: dict) -> None:
        index = self._output_index(obj.get("output_index"))
        content_index = obj.get("content_index", 0)
        if (type(content_index) is not int or content_index < 0 or content_index > 1_000_000
                or type(obj.get("delta")) is not str):
            raise DirectResponsesError("invalid_response", "sse")
        item_id = obj.get("item_id")
        if item_id is not None:
            self._check_item_id(item_id)
            old_id = self._delta_ids.setdefault(index, item_id)
            if old_id != item_id:
                raise DirectResponsesError("invalid_response", "sse")
        parts = self._deltas.setdefault(index, {})
        parts[content_index] = parts.get(content_index, "") + obj["delta"]
        size = sum(len(part.encode("utf-8")) for groups in self._deltas.values()
                   for part in groups.values())
        if size > self._limits.max_output_bytes:
            raise DirectResponsesError("output_limit", "sse")

    def _consume_completed_item(self, obj: dict) -> None:
        index = self._output_index(obj.get("output_index"))
        item = obj.get("item")
        if type(item) is not dict:
            raise DirectResponsesError("invalid_response", "sse")
        if item.get("type") == "reasoning":
            self._validate_reasoning_item(item, stage="output_item")
            return
        full_text = self._message_item_text(item, stage="output_item")
        item_id = item.get("id")
        if item_id is not None:
            self._check_item_id(item_id)
            delta_id = self._delta_ids.get(index)
            if delta_id is not None and delta_id != item_id:
                raise DirectResponsesError("invalid_response", "output_item")
        if index in self._completed:
            raise DirectResponsesError("invalid_response", "output_item")
        self._completed[index] = _CompletedOutput(index, item_id, full_text)

    def _terminal_snapshot_text(self, output: object) -> str:
        if type(output) is not list:
            raise DirectResponsesError("invalid_response", "terminal_output")
        if len(output) > self._limits.max_events:
            raise DirectResponsesError("response_limit", "terminal_output")
        messages = []
        for item in output:
            if type(item) is not dict:
                raise DirectResponsesError("invalid_response", "terminal_output")
            if item.get("type") == "reasoning":
                self._validate_reasoning_item(item, stage="terminal_output")
                continue
            messages.append(self._message_item_text(item, stage="terminal_output"))
        if len(messages) != 1:
            raise DirectResponsesError("invalid_response", "terminal_output")
        return messages[0]

    def _message_item_text(self, item: dict, *, stage: str) -> str:
        item_type = item.get("type")
        if item_type in _TOOL_ITEM_TYPES:
            raise DirectResponsesError("invalid_response", "tool_forbidden")
        if item_type != "message":
            raise DirectResponsesError("invalid_response", stage)
        if item.get("role") not in (None, "assistant"):
            raise DirectResponsesError("invalid_response", stage)
        if item.get("status") not in (None, "completed"):
            raise DirectResponsesError("invalid_response", stage)
        item_id = item.get("id")
        if item_id is not None:
            self._check_item_id(item_id)
        content = item.get("content")
        if type(content) is not list:
            raise DirectResponsesError("invalid_response", stage)
        if len(content) > self._limits.max_events:
            raise DirectResponsesError("response_limit", stage)
        texts = []
        for part in content:
            if type(part) is not dict:
                raise DirectResponsesError("invalid_response", stage)
            if part.get("type") != "output_text" or type(part.get("text")) is not str:
                raise DirectResponsesError("invalid_response", stage)
            texts.append(part["text"])
        full_text = "".join(texts)
        if not full_text:
            raise DirectResponsesError("invalid_response", stage)
        if len(full_text.encode("utf-8")) > self._limits.max_output_bytes:
            raise DirectResponsesError("output_limit", stage)
        return full_text

    def _validate_reasoning_item(self, item: dict, *, stage: str) -> None:
        """Validate known non-candidate reasoning structure, without retaining its text."""
        if item.get("status") not in (None, "completed"):
            raise DirectResponsesError("invalid_response", stage)
        item_id = item.get("id")
        if item_id is not None:
            self._check_item_id(item_id)
        encrypted_content = item.get("encrypted_content")
        if encrypted_content is not None and type(encrypted_content) is not str:
            raise DirectResponsesError("invalid_response", stage)
        for field, allowed_types in (
                ("summary", frozenset({"summary_text"})),
                ("content", frozenset({"reasoning_text", "summary_text"}))):
            parts = item.get(field)
            if parts is None:
                continue
            if type(parts) is not list:
                raise DirectResponsesError("invalid_response", stage)
            if len(parts) > self._limits.max_events:
                raise DirectResponsesError("response_limit", stage)
            for part in parts:
                if (type(part) is not dict or part.get("type") not in allowed_types
                        or type(part.get("text")) is not str):
                    raise DirectResponsesError("invalid_response", stage)

    def _assembled_candidate_text(self) -> str:
        if self._completed:
            if len(self._completed) != 1 or set(self._deltas) - set(self._completed):
                raise DirectResponsesError("invalid_response", "terminal_output")
            return next(iter(self._completed.values())).text
        if len(self._deltas) != 1:
            raise DirectResponsesError("invalid_response", "terminal_output")
        index, parts = next(iter(self._deltas.items()))
        text = "".join(parts[part] for part in sorted(parts))
        if not text:
            raise DirectResponsesError("invalid_response", "terminal_output")
        return text

    @staticmethod
    def _output_index(value: object) -> int:
        if type(value) is not int or not 0 <= value <= 1_000_000:
            raise DirectResponsesError("invalid_response", "sse")
        return value

    @staticmethod
    def _check_item_id(value: object) -> None:
        if (type(value) is not str or not value or len(value) > 256
                or any(ord(char) < 33 or ord(char) > 126 for char in value)):
            raise DirectResponsesError("invalid_response", "sse")

    def finish(self) -> list[str]:
        if not self._terminal:
            raise DirectResponsesError("invalid_response", "incomplete_stream")
        if self._failed:
            raise DirectResponsesError("invalid_response", "terminal")
        if self._completed:
            # A complete item is authoritative. Every text delta seen must refer to one of
            # those completed item indexes; no unfinished second answer is accepted.
            if set(self._deltas) - set(self._completed):
                raise DirectResponsesError("invalid_response", "incomplete_output")
            ordered = [self._completed[key].text for key in sorted(self._completed)]
        else:
            if not self._deltas:
                raise DirectResponsesError("invalid_response", "output_missing")
            ordered = ["".join(self._deltas[index][part]
                               for part in sorted(self._deltas[index]))
                       for index in sorted(self._deltas)]
        if len(ordered) != 1 or not ordered[0]:
            raise DirectResponsesError("invalid_response", "output_multiple")
        if len(ordered[0].encode("utf-8")) > self._limits.max_output_bytes:
            raise DirectResponsesError("output_limit", "validation")
        return ordered

"""Bounded TypeSafe input observations, never permissions or state mutations.

The caller separately authorizes transmission, account and spend. Default budget is
zero. Legacy calibration references remain distinct from the explicitly selected,
versioned user-development policy; neither adapter text nor a caller string is evidence
of statistical quality.
"""
