    choice_probability_sum_compatible,
)
from mira.application.choice_wire_policy import (
    CHOICE_WIRE_POLICY_LEGACY_STRICT, CHOICE_WIRE_POLICY_REPORTED_V2,
    is_supported_choice_wire_policy,
